// Builds synthetic, anonymised bank statements in the layouts Indian banks export.
// Every name, account number and amount here is made up. Run: node tests/fixtures/make-fixtures.mjs
import * as XLSX from "xlsx"
import fs from "node:fs"
import path from "node:path"
import { fileURLToPath } from "node:url"
XLSX.set_fs(fs)

const here = path.dirname(fileURLToPath(import.meta.url))
const narrations = ["UPI/ZOMATO/zomato@okaxis/Food order", "UPI/BLINKIT/blinkit@ybl/Groceries", "NEFT/ACME TECH PVT LTD/SALARY OCT", "ACH/DEMO MF SIP", "UPI/UBER INDIA/uber@icici/Ride", "ATM WDL/DEMO BRANCH"]
const rows = []
let balance = 25000
for (let i = 0; i < 24; i += 1) {
  const day = String((i % 28) + 1).padStart(2, "0")
  const credit = i === 2 ? 60000 : i === 15 ? 450.5 : 0
  const debit = credit ? 0 : [349, 812.4, 2500, 199, 1200, 75.25][i % 6]
  balance = Math.round((balance + credit - debit) * 100) / 100
  rows.push({ date: `${day}/09/2026`, narration: narrations[i % 6] + (i % 6 === 0 ? "/ref" + (100000 + i) : ""), debit, credit, balance })
}
const opening = 25000

// 1. ICICI-style detailed statement (.xls, BIFF8): preamble, S No., value + transaction date,
// remarks that wrap onto the next row at page breaks, legend lines below the table.
{
  const grid = [[], ["", "DETAILED STATEMENT"], ["", "Demo Bank"], ["", "Account Number", "", "XXXXXXXX1234 ( INR ) - DEMO USER"], ["", "Transaction Date from", "", "01/09/2026", "to", "30/09/2026"], [], ["", "Transactions List - DEMO USER - XXXXXXXX1234"],
    ["", "S No.", "Value Date", "Transaction Date", "Cheque Number", "Transaction Remarks", "Withdrawal Amount(INR)", "Deposit Amount(INR)", "Balance(INR)"]]
  rows.forEach((row, index) => {
    const wrap = index === 1 || index === 13
    const remark = wrap ? row.narration.slice(0, 18) : row.narration
    grid.push(["", String(index + 1), row.date, row.date, "", remark, row.debit.toFixed(2), row.credit.toFixed(2), row.balance.toFixed(2)])
    if (wrap) grid.push(["", "", "", "", "", row.narration.slice(18)])
  })
  grid.push([], ["", "Legends Used in Account Statement"], ["", "1. BIL - Internet Banking Bill Payment"], ["", "2. NEFT - National Electronic Funds Transfer"])
  const book = XLSX.utils.book_new()
  XLSX.utils.book_append_sheet(book, XLSX.utils.aoa_to_sheet(grid), "OpTransactionHistory")
  XLSX.writeFile(book, path.join(here, "icici-style.xls"), { bookType: "biff8" })
}

// 2. HTML table saved as .xls (common for older net-banking exports): single Amount + Dr/Cr column.
{
  const body = rows.map((row) => `<tr><td>${row.date.replace(/\//g, "-")}</td><td>${row.narration}</td><td>${(row.debit || row.credit).toFixed(2)}</td><td>${row.debit ? "DR" : "CR"}</td><td>${row.balance.toFixed(2)}</td></tr>`).join("\n")
  const html = `<html><body><table><tr><td colspan="5">Demo Co-operative Bank - Statement of Account</td></tr><tr><td>Customer</td><td>DEMO USER</td></tr>
<tr><td>Opening Balance</td><td></td><td>${opening.toFixed(2)}</td></tr>
<tr><th>Txn Date</th><th>Description</th><th>Amount</th><th>Dr/Cr</th><th>Balance</th></tr>
${body}
<tr><td>Closing Balance</td><td></td><td>${rows.at(-1).balance.toFixed(2)}</td></tr></table></body></html>`
  fs.writeFileSync(path.join(here, "html-disguised.xls"), html)
}

// 3. CSV with bank info above the header, "05 Sep 2026" dates, a summary block at the end.
{
  const lines = ["Demo Bank Ltd", "Statement for account XXXX5678", "", "Date,Narration,Chq./Ref.No.,Withdrawal (Dr),Deposit (Cr),Closing Balance", `,Opening Balance,,,,${opening.toFixed(2)}`]
  for (const row of rows) {
    const [d] = row.date.split("/")
    lines.push(`${d} Sep 2026,"${row.narration}",000${d},${row.debit ? row.debit.toFixed(2) : ""},${row.credit ? row.credit.toFixed(2) : ""},"${row.balance.toLocaleString("en-IN", { minimumFractionDigits: 2 })}"`)
  }
  lines.push("", "STATEMENT SUMMARY", "Opening Balance,Debits,Credits,Closing Balance", `${opening},1000,2000,${rows.at(-1).balance}`)
  fs.writeFileSync(path.join(here, "preamble.csv"), lines.join("\r\n"))
}

// 4. .xlsx with real Excel date cells and a signed single amount column.
{
  const grid = [["Demo Bank statement"], ["Posting Date", "Details", "Amount", "Balance"]]
  for (const row of rows) {
    const [d, m, y] = row.date.split("/").map(Number)
    grid.push([new Date(Date.UTC(y, m - 1, d)), row.narration, row.credit || -row.debit, row.balance])
  }
  grid.push(["Total", "", rows.reduce((s, r) => s + r.credit - r.debit, 0), ""])
  const sheet = XLSX.utils.aoa_to_sheet(grid, { cellDates: true, dateNF: "m/d/yy" })
  const book = XLSX.utils.book_new()
  XLSX.utils.book_append_sheet(book, XLSX.utils.aoa_to_sheet([["Generated by Demo Bank"]]), "Info")
  XLSX.utils.book_append_sheet(book, sheet, "Statement")
  XLSX.writeFile(book, path.join(here, "signed-amount.xlsx"))
}
fs.writeFileSync(path.join(here, "expected.json"), JSON.stringify({ rows: rows.length, opening, closing: rows.at(-1).balance, debits: rows.filter((r) => r.debit).length }, null, 2))
